mapper.select:
SELECT e.STATION_ID
FROM M_STATION_VERSION_LOG e
WHERE e.VERSION = #{version}

SELECT *
FROM M_STATION_VERSION_LOG e
WHERE id = (
    SELECT MAX(id)
    FROM M_STATION_VERSION_LOG t
    WHERE t.STATION_ID = #{stationId}
      AND t.STATUS = 'UPDATE_SUCCESS'
      AND t.JAR_NAME = #{jarName}
)

SELECT *
FROM M_STATION_VERSION_LOG e
WHERE id = (
    SELECT MAX(id)
    FROM M_STATION_VERSION_LOG t
    WHERE t.STATION_ID = #{stationId}
      AND t.STATUS = 'UPDATE_SUCCESS'
      AND t.VERSION_MSG_ID = #{versionMsgId}
)
